window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-70295554985bb1df"]={"versions": [{"id": "FIG-70295554985bb1df", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (State Machine Diagram) zur Spezifikation des Zustands- und Betriebsmodus-Verhaltens des AUTOSAR Classic Platform Basissoftware-Moduls FlexRay Network Management (<code>FrNm</code>). Das Diagramm definiert die übergeordneten Betriebsmodi (<code>Bus Sleep Mode</code>, <code>Synchronize</code>, <code>Network Mode</code>) sowie die hierarchischen Subzustände innerhalb des <code>Network Mode</code> (<code>Repeat Message</code>, <code>Normal Operation</code>, <code>Ready Sleep</code>) und deren Interaktion mit dem Zustand <code>Uninit</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Zustände:</strong>\n<ul class=\"fig-list\"><li><code>Uninit</code>: Initialer Ruhezustand vor der Modulinitialisierung.\n</li><li><code>Bus Sleep Mode</code>: Energiesparmodus ohne Kommunikation. Entry-Aktion: <code>FrNm_NetworkRequest = FALSE</code>, <code>FrNm_RepeatMessage = FALSE</code>.\n</li><li><code>Synchronize</code>: Synchronisationsphase zur Herstellung des globalen FlexRay-Zeittakts. Entry-Aktion: Benachrichtigung <code>Notify &quot;Sychronize Mode&quot;</code>.\n</li><li><code>Network Mode</code>: Zusammengesetzter Zustand (Composite State) mit den Subzuständen:\n<ul class=\"fig-list\"><li><code>Repeat Message</code>: Wiederholtes Senden von NM-Botschaften. Entry-Aktion: <code>Start RepeateMessage Timer</code>.\n</li><li><code>Normal Operation</code>: Regulärer aktiver NM-Betrieb mit Abstimmung zum Wachbleiben und Datenübertragung.\n</li><li><code>Ready Sleep</code>: Bereitschaft zum Übergang in den Schlafzustand; keine aktive Abstimmung zum Wachbleiben, keine Datenübertragung.\n</li></ul>\n</li></ul>\n</li><li><strong>Pseudozustände &amp; Endzustände:</strong>\n<ul class=\"fig-list\"><li>Initialzustände (Start-Pseudozustand) für Top-Level und Subzustände von <code>Network Mode</code>.\n</li><li>Verzweigungsknoten (Choice/Junction) für zyklische Überprüfungen und Bedingungsabzweige.\n</li><li>Terminierungs- bzw. Endzustand (<code>Terminate</code>) nach <code>Power Off</code>.\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Funktionsaufrufe (Trigger/Aktionen):</strong>\n<ul class=\"fig-list\"><li>APIs / Callbacks: <code>FrNm_Init()</code>, <code>FrNm_PassiveStartUp()</code>, <code>FrNm_NetworkRequest()</code>, <code>Nm_NetworkRequest()</code>, <code>FrNm_NetworkRelease()</code>.\n</li><li>Notifications: <code>/Notify &quot;Network Mode&quot;</code>, <code>/Nm_BusSleepMode</code>.\n</li><li>Interne Signale/Ereignisse: <code>RepeatMessagDetected</code>, <code>RepeatMessageTimer expired</code>, <code>Repetition Cycle completed</code>, <code>ClusterAwakeVote detected</code>, <code>Retrieve global time fails</code>.\n</li></ul>\n</li><li><strong>Statusvariablen &amp; Zähler:</strong>\n<ul class=\"fig-list\"><li><code>FrNm_NetworkRequest</code> (BOOLEAN)\n</li><li><code>FrNm_RepeatMessage</code> (BOOLEAN)\n</li><li><code>FrNm_ReadySleepCnt</code> (Ganzzahl/Zähler)\n</li><li>Konfigurationsparameter: <code>FrNmCycleCounterEmulation</code>, <code>StartValue</code>.\n</li></ul>\n</li><li><strong>Kommentar-Notizen:</strong>\n<ul class=\"fig-list\"><li>Kennzeichnung des Sende- und Abstimmungsverhaltens je Zustand (<code>Vote for keeping awake, Do data transmission</code> bzw. <code>No voting for keeping awake, No data transmission</code>).\n</li><li>Ausführungsbedingung für den Übergang aus <code>Network Mode</code> nach <code>Bus Sleep Mode</code>: sofortige Ausführung bei wahrer Guard-Bedingung im aktuellen MainFunction-Zyklus.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Initialisierung &amp; Hochlauf:</strong>\n<ul class=\"fig-list\"><li>Nach Systemstart (<code>Start</code>) befindet sich das Modul in <code>Uninit</code>.\n</li><li><code>FrNm_Init()</code> führt in den <code>Bus Sleep Mode</code>.\n</li><li>Aus <code>Bus Sleep Mode</code> führt <code>FrNm_PassiveStartUp()</code> oder <code>FrNm_NetworkRequest()</code> (mit Setzen von <code>FrNm_NetworkRequest = TRUE</code>) in den Zustand <code>Synchronize</code>.\n</li></ul>\n</li><li><strong>Synchronisation:</strong>\n<ul class=\"fig-list\"><li>In <code>Synchronize</code> wird auf den FlexRay-Zyklus aufsynchronisiert.\n</li><li>Bei erfolgreichem Zyklus (<code>Repetition Cycle completed</code>) erfolgt der Übergang in den <code>Network Mode</code> über einen Verzweigungspunkt: Wurde ein Netzwerk angefordert (<code>FrNm_NetworkRequest == TRUE</code>), führt der Pfad mit Aktion <code>/Notify &quot;Network Mode&quot;</code> und <code>FrNm_RepeatMessage = TRUE</code> in <code>Repeat Message</code>.\n</li><li>Schlägt die Synchronisation fehl (<code>Retrieve global time fails</code>), führt die Transition zurück nach <code>Synchronize</code>.\n</li><li>Reinitialisierung über <code>FrNm_Init()</code> oder Fehler (<code>[FrNm_Init OR (FrNm_NetworkRequested == FALSE AND FrNm_StartUp_Error Indication)]</code>) führt zurück in <code>Bus Sleep Mode</code>.\n</li></ul>\n</li><li><strong>Network Mode Zyklen &amp; Zustandswechsel:</strong>\n<ul class=\"fig-list\"><li>Nach Eintritt in <code>Network Mode</code> startet der Subzustand <code>Repeat Message</code> mit dem <code>RepeateMessage Timer</code>.\n</li><li>Bei Ablauf des Wiederholungszyklus (<code>Repetition Cycle completed</code>):\n<ul class=\"fig-list\"><li>Ist <code>FrNm_NetworkRequest == TRUE</code> und <code>FrNm_RepeatMessage == FALSE</code>, wechselt der Zustand zu <code>Normal Operation</code>.\n</li><li>Ist <code>FrNm_NetworkRequest == FALSE</code> und <code>FrNm_RepeatMessage == FALSE</code>, wechselt der Zustand zu <code>Ready Sleep</code> unter Initialisierung von <code>FrNm_ReadySleepCnt = StartValue</code>.\n</li><li>Ist <code>FrNm_ReadySleepCnt &gt; 0</code> und <code>FrNm_RepeatMessage == TRUE</code>, verbleibt bzw. verzweigt der Pfad in <code>Repeat Message</code>.\n</li></ul>\n</li><li>In <code>Normal Operation</code>:\n<ul class=\"fig-list\"><li><code>FrNm_NetworkRelease()</code> setzt <code>FrNm_NetworkRequest = FALSE</code>.\n</li><li>Bei <code>Repetition Cycle completed [FrNm_NetworkRequest=FALSE AND FrNm_RepeatMessage=FALSE]</code> erfolgt der Wechsel nach <code>Ready Sleep</code> mit Zählerbelegung <code>FrNm_ReadySleepCnt = StartValue</code>.\n</li></ul>\n</li><li>In <code>Ready Sleep</code>:\n<ul class=\"fig-list\"><li>Solange <code>FrNm_NetworkRequest == FALSE AND FrNm_RepeatMessage == FALSE AND FrNm_ReadSleepCnt &gt; 0</code>, dekrementiert jeder Zyklus den Zähler: <code>/FrNm_ReadySleepCnt = FrNm_ReadySleepCnt - 1</code>.\n</li><li>Wird eine Netzwerkanforderung empfangen (<code>FrNm_NetworkRequest()</code>), wird <code>FrNm_NetworkRequest = TRUE</code> gesetzt und bei <code>FrNm_ReadySleepCnt &gt; 0</code> nach <code>Normal Operation</code> gewechselt.\n</li><li>Wird ein <code>ClusterAwakeVote detected</code>, wird <code>FrNm_ReadySleepCnt = StartValue</code> neu gesetzt.\n</li><li>Wenn <code>Repetition Cycle completed [FrNm_ReadySleepCnt &lt; 1]</code> eintritt, erfolgt über eine Exit-Verzweigung der Verlassen-Übergang von <code>Network Mode</code> in <code>Bus Sleep Mode</code> unter Auslösung von <code>/Nm_BusSleepMode</code>.\n</li></ul>\n</li><li>Übergeordnete Fehlerübergänge aus <code>Network Mode</code>:\n<ul class=\"fig-list\"><li><code>Retrieve global time fails [FrNmCycleCounterEmulation == FALSE AND Network is requested]</code> führt zurück nach <code>Synchronize</code>.\n</li><li>Reinitialisierung <code>FrNm_Init()</code> führt direkt nach <code>Bus Sleep Mode</code>.\n</li></ul>\n</li></ul>\n</li><li><strong>Herunterfahren:</strong>\n<ul class=\"fig-list\"><li>Aus <code>Bus Sleep Mode</code> führt <code>Power Off</code> in den Endzustand <code>Terminate</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Das Zustandsmodell legt die normativen Anforderungen an das AUTOSAR Classic FlexRay Network Management Modul fest.\n</li><li>Implementierer müssen sicherstellen, dass Guards unmittelbar im Zyklus der <code>FrNm_MainFunction</code> evaluiert und Transitionen verzögerungsfrei abgearbeitet werden, insbesondere beim Verlassen des <code>Network Mode</code> bei abgelaufenem <code>FrNm_ReadySleepCnt</code>.\n</li><li>Korrekte Pflege und synchrone Zählung von <code>FrNm_ReadySleepCnt</code> sowie das Rücksetzen bei externen Wachhalte-Votings (<code>ClusterAwakeVote detected</code>) sind essenziell für die koordinierte Cluster-Abschaltung.\n</li><li>Die Emulation des Zykluszählers (<code>FrNmCycleCounterEmulation</code>) bestimmt das Verhalten bei Verlust der globalen Zeitbasis.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-618a12c348b10353", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (State Machine Diagram) zur Spezifikation des Zustands- und Betriebsmodus-Verhaltens des AUTOSAR Classic Platform Basissoftware-Moduls FlexRay Network Management (<code>FrNm</code>). Das Diagramm definiert die übergeordneten Betriebsmodi (<code>Bus Sleep Mode</code>, <code>Synchronize</code>, <code>Network Mode</code>) sowie die hierarchischen Subzustände innerhalb des <code>Network Mode</code> (<code>Repeat Message</code>, <code>Normal Operation</code>, <code>Ready Sleep</code>) und deren Interaktion mit dem Zustand <code>Uninit</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Zustände:</strong>\n<ul class=\"fig-list\"><li><code>Uninit</code>: Initialer Ruhezustand vor der Modulinitialisierung.\n</li><li><code>Bus Sleep Mode</code>: Energiesparmodus ohne Kommunikation. Entry-Aktion: <code>FrNm_NetworkRequest = FALSE</code>, <code>FrNm_RepeatMessage = FALSE</code>.\n</li><li><code>Synchronize</code>: Synchronisationsphase zur Herstellung des globalen FlexRay-Zeittakts. Entry-Aktion: Benachrichtigung <code>Notify &quot;Sychronize Mode&quot;</code>.\n</li><li><code>Network Mode</code>: Zusammengesetzter Zustand (Composite State) mit den Subzuständen:\n<ul class=\"fig-list\"><li><code>Repeat Message</code>: Wiederholtes Senden von NM-Botschaften. Entry-Aktion: <code>Start RepeateMessage Timer</code>.\n</li><li><code>Normal Operation</code>: Regulärer aktiver NM-Betrieb mit Abstimmung zum Wachbleiben und Datenübertragung.\n</li><li><code>Ready Sleep</code>: Bereitschaft zum Übergang in den Schlafzustand; keine aktive Abstimmung zum Wachbleiben, keine Datenübertragung.\n</li></ul>\n</li></ul>\n</li><li><strong>Pseudozustände &amp; Endzustände:</strong>\n<ul class=\"fig-list\"><li>Initialzustände (Start-Pseudozustand) für Top-Level und Subzustände von <code>Network Mode</code>.\n</li><li>Verzweigungsknoten (Choice/Junction) für zyklische Überprüfungen und Bedingungsabzweige.\n</li><li>Terminierungs- bzw. Endzustand (<code>Terminate</code>) nach <code>Power Off</code>.\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Funktionsaufrufe (Trigger/Aktionen):</strong>\n<ul class=\"fig-list\"><li>APIs / Callbacks: <code>FrNm_Init()</code>, <code>FrNm_PassiveStartUp()</code>, <code>FrNm_NetworkRequest()</code>, <code>Nm_NetworkRequest()</code>, <code>FrNm_NetworkRelease()</code>.\n</li><li>Notifications: <code>/Notify &quot;Network Mode&quot;</code>, <code>/Nm_BusSleepMode</code>.\n</li><li>Interne Signale/Ereignisse: <code>RepeatMessagDetected</code>, <code>RepeatMessageTimer expired</code>, <code>Repetition Cycle completed</code>, <code>ClusterAwakeVote detected</code>, <code>Retrieve global time fails</code>.\n</li></ul>\n</li><li><strong>Statusvariablen &amp; Zähler:</strong>\n<ul class=\"fig-list\"><li><code>FrNm_NetworkRequest</code> (BOOLEAN)\n</li><li><code>FrNm_RepeatMessage</code> (BOOLEAN)\n</li><li><code>FrNm_ReadySleepCnt</code> (Ganzzahl/Zähler)\n</li><li>Konfigurationsparameter: <code>FrNmCycleCounterEmulation</code>, <code>StartValue</code>.\n</li></ul>\n</li><li><strong>Kommentar-Notizen:</strong>\n<ul class=\"fig-list\"><li>Kennzeichnung des Sende- und Abstimmungsverhaltens je Zustand (<code>Vote for keeping awake, Do data transmission</code> bzw. <code>No voting for keeping awake, No data transmission</code>).\n</li><li>Ausführungsbedingung für den Übergang aus <code>Network Mode</code> nach <code>Bus Sleep Mode</code>: sofortige Ausführung bei wahrer Guard-Bedingung im aktuellen MainFunction-Zyklus.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Initialisierung &amp; Hochlauf:</strong>\n<ul class=\"fig-list\"><li>Nach Systemstart (<code>Start</code>) befindet sich das Modul in <code>Uninit</code>.\n</li><li><code>FrNm_Init()</code> führt in den <code>Bus Sleep Mode</code>.\n</li><li>Aus <code>Bus Sleep Mode</code> führt <code>FrNm_PassiveStartUp()</code> oder <code>FrNm_NetworkRequest()</code> (mit Setzen von <code>FrNm_NetworkRequest = TRUE</code>) in den Zustand <code>Synchronize</code>.\n</li></ul>\n</li><li><strong>Synchronisation:</strong>\n<ul class=\"fig-list\"><li>In <code>Synchronize</code> wird auf den FlexRay-Zyklus aufsynchronisiert.\n</li><li>Bei erfolgreichem Zyklus (<code>Repetition Cycle completed</code>) erfolgt der Übergang in den <code>Network Mode</code> über einen Verzweigungspunkt: Wurde ein Netzwerk angefordert (<code>FrNm_NetworkRequest == TRUE</code>), führt der Pfad mit Aktion <code>/Notify &quot;Network Mode&quot;</code> und <code>FrNm_RepeatMessage = TRUE</code> in <code>Repeat Message</code>.\n</li><li>Schlägt die Synchronisation fehl (<code>Retrieve global time fails</code>), führt die Transition zurück nach <code>Synchronize</code>.\n</li><li>Reinitialisierung über <code>FrNm_Init()</code> oder Fehler (<code>[FrNm_Init OR (FrNm_NetworkRequested == FALSE AND FrNm_StartUp_Error Indication)]</code>) führt zurück in <code>Bus Sleep Mode</code>.\n</li></ul>\n</li><li><strong>Network Mode Zyklen &amp; Zustandswechsel:</strong>\n<ul class=\"fig-list\"><li>Nach Eintritt in <code>Network Mode</code> startet der Subzustand <code>Repeat Message</code> mit dem <code>RepeateMessage Timer</code>.\n</li><li>Bei Ablauf des Wiederholungszyklus (<code>Repetition Cycle completed</code>):\n<ul class=\"fig-list\"><li>Ist <code>FrNm_NetworkRequest == TRUE</code> und <code>FrNm_RepeatMessage == FALSE</code>, wechselt der Zustand zu <code>Normal Operation</code>.\n</li><li>Ist <code>FrNm_NetworkRequest == FALSE</code> und <code>FrNm_RepeatMessage == FALSE</code>, wechselt der Zustand zu <code>Ready Sleep</code> unter Initialisierung von <code>FrNm_ReadySleepCnt = StartValue</code>.\n</li><li>Ist <code>FrNm_ReadySleepCnt &gt; 0</code> und <code>FrNm_RepeatMessage == TRUE</code>, verbleibt bzw. verzweigt der Pfad in <code>Repeat Message</code>.\n</li></ul>\n</li><li>In <code>Normal Operation</code>:\n<ul class=\"fig-list\"><li><code>FrNm_NetworkRelease()</code> setzt <code>FrNm_NetworkRequest = FALSE</code>.\n</li><li>Bei <code>Repetition Cycle completed [FrNm_NetworkRequest=FALSE AND FrNm_RepeatMessage=FALSE]</code> erfolgt der Wechsel nach <code>Ready Sleep</code> mit Zählerbelegung <code>FrNm_ReadySleepCnt = StartValue</code>.\n</li></ul>\n</li><li>In <code>Ready Sleep</code>:\n<ul class=\"fig-list\"><li>Solange <code>FrNm_NetworkRequest == FALSE AND FrNm_RepeatMessage == FALSE AND FrNm_ReadSleepCnt &gt; 0</code>, dekrementiert jeder Zyklus den Zähler: <code>/FrNm_ReadySleepCnt = FrNm_ReadySleepCnt - 1</code>.\n</li><li>Wird eine Netzwerkanforderung empfangen (<code>FrNm_NetworkRequest()</code>), wird <code>FrNm_NetworkRequest = TRUE</code> gesetzt und bei <code>FrNm_ReadySleepCnt &gt; 0</code> nach <code>Normal Operation</code> gewechselt.\n</li><li>Wird ein <code>ClusterAwakeVote detected</code>, wird <code>FrNm_ReadySleepCnt = StartValue</code> neu gesetzt.\n</li><li>Wenn <code>Repetition Cycle completed [FrNm_ReadySleepCnt &lt; 1]</code> eintritt, erfolgt über eine Exit-Verzweigung der Verlassen-Übergang von <code>Network Mode</code> in <code>Bus Sleep Mode</code> unter Auslösung von <code>/Nm_BusSleepMode</code>.\n</li></ul>\n</li><li>Übergeordnete Fehlerübergänge aus <code>Network Mode</code>:\n<ul class=\"fig-list\"><li><code>Retrieve global time fails [FrNmCycleCounterEmulation == FALSE AND Network is requested]</code> führt zurück nach <code>Synchronize</code>.\n</li><li>Reinitialisierung <code>FrNm_Init()</code> führt direkt nach <code>Bus Sleep Mode</code>.\n</li></ul>\n</li></ul>\n</li><li><strong>Herunterfahren:</strong>\n<ul class=\"fig-list\"><li>Aus <code>Bus Sleep Mode</code> führt <code>Power Off</code> in den Endzustand <code>Terminate</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Das Zustandsmodell legt die normativen Anforderungen an das AUTOSAR Classic FlexRay Network Management Modul fest.\n</li><li>Implementierer müssen sicherstellen, dass Guards unmittelbar im Zyklus der <code>FrNm_MainFunction</code> evaluiert und Transitionen verzögerungsfrei abgearbeitet werden, insbesondere beim Verlassen des <code>Network Mode</code> bei abgelaufenem <code>FrNm_ReadySleepCnt</code>.\n</li><li>Korrekte Pflege und synchrone Zählung von <code>FrNm_ReadySleepCnt</code> sowie das Rücksetzen bei externen Wachhalte-Votings (<code>ClusterAwakeVote detected</code>) sind essenziell für die koordinierte Cluster-Abschaltung.\n</li><li>Die Emulation des Zykluszählers (<code>FrNmCycleCounterEmulation</code>) bestimmt das Verhalten bei Verlust der globalen Zeitbasis.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-049daa5ed1aeb697", "releases": ["R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (State Machine Diagram) zur Spezifikation des Zustands- und Betriebsmodus-Verhaltens des AUTOSAR Classic Platform Basissoftware-Moduls FlexRay Network Management (<code>FrNm</code>). Das Diagramm definiert die übergeordneten Betriebsmodi (<code>Bus Sleep Mode</code>, <code>Synchronize</code>, <code>Network Mode</code>) sowie die hierarchischen Subzustände innerhalb des <code>Network Mode</code> (<code>Repeat Message</code>, <code>Normal Operation</code>, <code>Ready Sleep</code>) und deren Interaktion mit dem Zustand <code>Uninit</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Zustände:</strong>\n<ul class=\"fig-list\"><li><code>Uninit</code>: Initialer Ruhezustand vor der Modulinitialisierung.\n</li><li><code>Bus Sleep Mode</code>: Energiesparmodus ohne Kommunikation. Entry-Aktion: <code>FrNm_NetworkRequest = FALSE</code>, <code>FrNm_RepeatMessage = FALSE</code>.\n</li><li><code>Synchronize</code>: Synchronisationsphase zur Herstellung des globalen FlexRay-Zeittakts. Entry-Aktion: Benachrichtigung <code>Notify &quot;Sychronize Mode&quot;</code>.\n</li><li><code>Network Mode</code>: Zusammengesetzter Zustand (Composite State) mit den Subzuständen:\n<ul class=\"fig-list\"><li><code>Repeat Message</code>: Wiederholtes Senden von NM-Botschaften. Entry-Aktion: <code>Start RepeateMessage Timer</code>.\n</li><li><code>Normal Operation</code>: Regulärer aktiver NM-Betrieb mit Abstimmung zum Wachbleiben und Datenübertragung.\n</li><li><code>Ready Sleep</code>: Bereitschaft zum Übergang in den Schlafzustand; keine aktive Abstimmung zum Wachbleiben, keine Datenübertragung.\n</li></ul>\n</li></ul>\n</li><li><strong>Pseudozustände &amp; Endzustände:</strong>\n<ul class=\"fig-list\"><li>Initialzustände (Start-Pseudozustand) für Top-Level und Subzustände von <code>Network Mode</code>.\n</li><li>Verzweigungsknoten (Choice/Junction) für zyklische Überprüfungen und Bedingungsabzweige.\n</li><li>Terminierungs- bzw. Endzustand (<code>Terminate</code>) nach <code>Power Off</code>.\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Funktionsaufrufe (Trigger/Aktionen):</strong>\n<ul class=\"fig-list\"><li>APIs / Callbacks: <code>FrNm_Init()</code>, <code>FrNm_PassiveStartUp()</code>, <code>FrNm_NetworkRequest()</code>, <code>Nm_NetworkRequest()</code>, <code>FrNm_NetworkRelease()</code>.\n</li><li>Notifications: <code>/Notify &quot;Network Mode&quot;</code>, <code>/Nm_BusSleepMode</code>.\n</li><li>Interne Signale/Ereignisse: <code>RepeatMessagDetected</code>, <code>RepeatMessageTimer expired</code>, <code>Repetition Cycle completed</code>, <code>ClusterAwakeVote detected</code>, <code>Retrieve global time fails</code>.\n</li></ul>\n</li><li><strong>Statusvariablen &amp; Zähler:</strong>\n<ul class=\"fig-list\"><li><code>FrNm_NetworkRequest</code> (BOOLEAN)\n</li><li><code>FrNm_RepeatMessage</code> (BOOLEAN)\n</li><li><code>FrNm_ReadySleepCnt</code> (Ganzzahl/Zähler)\n</li><li>Konfigurationsparameter: <code>FrNmCycleCounterEmulation</code>, <code>StartValue</code>.\n</li></ul>\n</li><li><strong>Kommentar-Notizen:</strong>\n<ul class=\"fig-list\"><li>Kennzeichnung des Sende- und Abstimmungsverhaltens je Zustand (<code>Vote for keeping awake, Do data transmission</code> bzw. <code>No voting for keeping awake, No data transmission</code>).\n</li><li>Ausführungsbedingung für den Übergang aus <code>Network Mode</code> nach <code>Bus Sleep Mode</code>: sofortige Ausführung bei wahrer Guard-Bedingung im aktuellen MainFunction-Zyklus.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Initialisierung &amp; Hochlauf:</strong>\n<ul class=\"fig-list\"><li>Nach Systemstart (<code>Start</code>) befindet sich das Modul in <code>Uninit</code>.\n</li><li><code>FrNm_Init()</code> führt in den <code>Bus Sleep Mode</code>.\n</li><li>Aus <code>Bus Sleep Mode</code> führt <code>FrNm_PassiveStartUp()</code> oder <code>FrNm_NetworkRequest()</code> (mit Setzen von <code>FrNm_NetworkRequest = TRUE</code>) in den Zustand <code>Synchronize</code>.\n</li></ul>\n</li><li><strong>Synchronisation:</strong>\n<ul class=\"fig-list\"><li>In <code>Synchronize</code> wird auf den FlexRay-Zyklus aufsynchronisiert.\n</li><li>Bei erfolgreichem Zyklus (<code>Repetition Cycle completed</code>) erfolgt der Übergang in den <code>Network Mode</code> über einen Verzweigungspunkt: Wurde ein Netzwerk angefordert (<code>FrNm_NetworkRequest == TRUE</code>), führt der Pfad mit Aktion <code>/Notify &quot;Network Mode&quot;</code> und <code>FrNm_RepeatMessage = TRUE</code> in <code>Repeat Message</code>.\n</li><li>Schlägt die Synchronisation fehl (<code>Retrieve global time fails</code>), führt die Transition zurück nach <code>Synchronize</code>.\n</li><li>Reinitialisierung über <code>FrNm_Init()</code> oder Fehler (<code>[FrNm_Init OR (FrNm_NetworkRequested == FALSE AND FrNm_StartUp_Error Indication)]</code>) führt zurück in <code>Bus Sleep Mode</code>.\n</li></ul>\n</li><li><strong>Network Mode Zyklen &amp; Zustandswechsel:</strong>\n<ul class=\"fig-list\"><li>Nach Eintritt in <code>Network Mode</code> startet der Subzustand <code>Repeat Message</code> mit dem <code>RepeateMessage Timer</code>.\n</li><li>Bei Ablauf des Wiederholungszyklus (<code>Repetition Cycle completed</code>):\n<ul class=\"fig-list\"><li>Ist <code>FrNm_NetworkRequest == TRUE</code> und <code>FrNm_RepeatMessage == FALSE</code>, wechselt der Zustand zu <code>Normal Operation</code>.\n</li><li>Ist <code>FrNm_NetworkRequest == FALSE</code> und <code>FrNm_RepeatMessage == FALSE</code>, wechselt der Zustand zu <code>Ready Sleep</code> unter Initialisierung von <code>FrNm_ReadySleepCnt = StartValue</code>.\n</li><li>Ist <code>FrNm_ReadySleepCnt &gt; 0</code> und <code>FrNm_RepeatMessage == TRUE</code>, verbleibt bzw. verzweigt der Pfad in <code>Repeat Message</code>.\n</li></ul>\n</li><li>In <code>Normal Operation</code>:\n<ul class=\"fig-list\"><li><code>FrNm_NetworkRelease()</code> setzt <code>FrNm_NetworkRequest = FALSE</code>.\n</li><li>Bei <code>Repetition Cycle completed [FrNm_NetworkRequest=FALSE AND FrNm_RepeatMessage=FALSE]</code> erfolgt der Wechsel nach <code>Ready Sleep</code> mit Zählerbelegung <code>FrNm_ReadySleepCnt = StartValue</code>.\n</li></ul>\n</li><li>In <code>Ready Sleep</code>:\n<ul class=\"fig-list\"><li>Solange <code>FrNm_NetworkRequest == FALSE AND FrNm_RepeatMessage == FALSE AND FrNm_ReadSleepCnt &gt; 0</code>, dekrementiert jeder Zyklus den Zähler: <code>/FrNm_ReadySleepCnt = FrNm_ReadySleepCnt - 1</code>.\n</li><li>Wird eine Netzwerkanforderung empfangen (<code>FrNm_NetworkRequest()</code>), wird <code>FrNm_NetworkRequest = TRUE</code> gesetzt und bei <code>FrNm_ReadySleepCnt &gt; 0</code> nach <code>Normal Operation</code> gewechselt.\n</li><li>Wird ein <code>ClusterAwakeVote detected</code>, wird <code>FrNm_ReadySleepCnt = StartValue</code> neu gesetzt.\n</li><li>Wenn <code>Repetition Cycle completed [FrNm_ReadySleepCnt &lt; 1]</code> eintritt, erfolgt über eine Exit-Verzweigung der Verlassen-Übergang von <code>Network Mode</code> in <code>Bus Sleep Mode</code> unter Auslösung von <code>/Nm_BusSleepMode</code>.\n</li></ul>\n</li><li>Übergeordnete Fehlerübergänge aus <code>Network Mode</code>:\n<ul class=\"fig-list\"><li><code>Retrieve global time fails [FrNmCycleCounterEmulation == FALSE AND Network is requested]</code> führt zurück nach <code>Synchronize</code>.\n</li><li>Reinitialisierung <code>FrNm_Init()</code> führt direkt nach <code>Bus Sleep Mode</code>.\n</li></ul>\n</li></ul>\n</li><li><strong>Herunterfahren:</strong>\n<ul class=\"fig-list\"><li>Aus <code>Bus Sleep Mode</code> führt <code>Power Off</code> in den Endzustand <code>Terminate</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Das Zustandsmodell legt die normativen Anforderungen an das AUTOSAR Classic FlexRay Network Management Modul fest.\n</li><li>Implementierer müssen sicherstellen, dass Guards unmittelbar im Zyklus der <code>FrNm_MainFunction</code> evaluiert und Transitionen verzögerungsfrei abgearbeitet werden, insbesondere beim Verlassen des <code>Network Mode</code> bei abgelaufenem <code>FrNm_ReadySleepCnt</code>.\n</li><li>Korrekte Pflege und synchrone Zählung von <code>FrNm_ReadySleepCnt</code> sowie das Rücksetzen bei externen Wachhalte-Votings (<code>ClusterAwakeVote detected</code>) sind essenziell für die koordinierte Cluster-Abschaltung.\n</li><li>Die Emulation des Zykluszählers (<code>FrNmCycleCounterEmulation</code>) bestimmt das Verhalten bei Verlust der globalen Zeitbasis.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-17c44f137303b916", "releases": ["R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (State Machine Diagram) zur Spezifikation des Zustands- und Betriebsmodus-Verhaltens des AUTOSAR Classic Platform Basissoftware-Moduls FlexRay Network Management (<code>FrNm</code>). Das Diagramm definiert die übergeordneten Betriebsmodi (<code>Bus Sleep Mode</code>, <code>Synchronize</code>, <code>Network Mode</code>) sowie die hierarchischen Subzustände innerhalb des <code>Network Mode</code> (<code>Repeat Message</code>, <code>Normal Operation</code>, <code>Ready Sleep</code>) und deren Interaktion mit dem Zustand <code>Uninit</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Zustände:</strong>\n<ul class=\"fig-list\"><li><code>Uninit</code>: Initialer Ruhezustand vor der Modulinitialisierung.\n</li><li><code>Bus Sleep Mode</code>: Energiesparmodus ohne Kommunikation. Entry-Aktion: <code>FrNm_NetworkRequest = FALSE</code>, <code>FrNm_RepeatMessage = FALSE</code>.\n</li><li><code>Synchronize</code>: Synchronisationsphase zur Herstellung des globalen FlexRay-Zeittakts. Entry-Aktion: Benachrichtigung <code>Notify &quot;Sychronize Mode&quot;</code>.\n</li><li><code>Network Mode</code>: Zusammengesetzter Zustand (Composite State) mit den Subzuständen:\n<ul class=\"fig-list\"><li><code>Repeat Message</code>: Wiederholtes Senden von NM-Botschaften. Entry-Aktion: <code>Start RepeateMessage Timer</code>.\n</li><li><code>Normal Operation</code>: Regulärer aktiver NM-Betrieb mit Abstimmung zum Wachbleiben und Datenübertragung.\n</li><li><code>Ready Sleep</code>: Bereitschaft zum Übergang in den Schlafzustand; keine aktive Abstimmung zum Wachbleiben, keine Datenübertragung.\n</li></ul>\n</li></ul>\n</li><li><strong>Pseudozustände &amp; Endzustände:</strong>\n<ul class=\"fig-list\"><li>Initialzustände (Start-Pseudozustand) für Top-Level und Subzustände von <code>Network Mode</code>.\n</li><li>Verzweigungsknoten (Choice/Junction) für zyklische Überprüfungen und Bedingungsabzweige.\n</li><li>Terminierungs- bzw. Endzustand (<code>Terminate</code>) nach <code>Power Off</code>.\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Funktionsaufrufe (Trigger/Aktionen):</strong>\n<ul class=\"fig-list\"><li>APIs / Callbacks: <code>FrNm_Init()</code>, <code>FrNm_PassiveStartUp()</code>, <code>FrNm_NetworkRequest()</code>, <code>Nm_NetworkRequest()</code>, <code>FrNm_NetworkRelease()</code>.\n</li><li>Notifications: <code>/Notify &quot;Network Mode&quot;</code>, <code>/Nm_BusSleepMode</code>.\n</li><li>Interne Signale/Ereignisse: <code>RepeatMessagDetected</code>, <code>RepeatMessageTimer expired</code>, <code>Repetition Cycle completed</code>, <code>ClusterAwakeVote detected</code>, <code>Retrieve global time fails</code>.\n</li></ul>\n</li><li><strong>Statusvariablen &amp; Zähler:</strong>\n<ul class=\"fig-list\"><li><code>FrNm_NetworkRequest</code> (BOOLEAN)\n</li><li><code>FrNm_RepeatMessage</code> (BOOLEAN)\n</li><li><code>FrNm_ReadySleepCnt</code> (Ganzzahl/Zähler)\n</li><li>Konfigurationsparameter: <code>FrNmCycleCounterEmulation</code>, <code>StartValue</code>.\n</li></ul>\n</li><li><strong>Kommentar-Notizen:</strong>\n<ul class=\"fig-list\"><li>Kennzeichnung des Sende- und Abstimmungsverhaltens je Zustand (<code>Vote for keeping awake, Do data transmission</code> bzw. <code>No voting for keeping awake, No data transmission</code>).\n</li><li>Ausführungsbedingung für den Übergang aus <code>Network Mode</code> nach <code>Bus Sleep Mode</code>: sofortige Ausführung bei wahrer Guard-Bedingung im aktuellen MainFunction-Zyklus.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Initialisierung &amp; Hochlauf:</strong>\n<ul class=\"fig-list\"><li>Nach Systemstart (<code>Start</code>) befindet sich das Modul in <code>Uninit</code>.\n</li><li><code>FrNm_Init()</code> führt in den <code>Bus Sleep Mode</code>.\n</li><li>Aus <code>Bus Sleep Mode</code> führt <code>FrNm_PassiveStartUp()</code> oder <code>FrNm_NetworkRequest()</code> (mit Setzen von <code>FrNm_NetworkRequest = TRUE</code>) in den Zustand <code>Synchronize</code>.\n</li></ul>\n</li><li><strong>Synchronisation:</strong>\n<ul class=\"fig-list\"><li>In <code>Synchronize</code> wird auf den FlexRay-Zyklus aufsynchronisiert.\n</li><li>Bei erfolgreichem Zyklus (<code>Repetition Cycle completed</code>) erfolgt der Übergang in den <code>Network Mode</code> über einen Verzweigungspunkt: Wurde ein Netzwerk angefordert (<code>FrNm_NetworkRequest == TRUE</code>), führt der Pfad mit Aktion <code>/Notify &quot;Network Mode&quot;</code> und <code>FrNm_RepeatMessage = TRUE</code> in <code>Repeat Message</code>.\n</li><li>Schlägt die Synchronisation fehl (<code>Retrieve global time fails</code>), führt die Transition zurück nach <code>Synchronize</code>.\n</li><li>Reinitialisierung über <code>FrNm_Init()</code> oder Fehler (<code>[FrNm_Init OR (FrNm_NetworkRequested == FALSE AND FrNm_StartUp_Error Indication)]</code>) führt zurück in <code>Bus Sleep Mode</code>.\n</li></ul>\n</li><li><strong>Network Mode Zyklen &amp; Zustandswechsel:</strong>\n<ul class=\"fig-list\"><li>Nach Eintritt in <code>Network Mode</code> startet der Subzustand <code>Repeat Message</code> mit dem <code>RepeateMessage Timer</code>.\n</li><li>Bei Ablauf des Wiederholungszyklus (<code>Repetition Cycle completed</code>):\n<ul class=\"fig-list\"><li>Ist <code>FrNm_NetworkRequest == TRUE</code> und <code>FrNm_RepeatMessage == FALSE</code>, wechselt der Zustand zu <code>Normal Operation</code>.\n</li><li>Ist <code>FrNm_NetworkRequest == FALSE</code> und <code>FrNm_RepeatMessage == FALSE</code>, wechselt der Zustand zu <code>Ready Sleep</code> unter Initialisierung von <code>FrNm_ReadySleepCnt = StartValue</code>.\n</li><li>Ist <code>FrNm_ReadySleepCnt &gt; 0</code> und <code>FrNm_RepeatMessage == TRUE</code>, verbleibt bzw. verzweigt der Pfad in <code>Repeat Message</code>.\n</li></ul>\n</li><li>In <code>Normal Operation</code>:\n<ul class=\"fig-list\"><li><code>FrNm_NetworkRelease()</code> setzt <code>FrNm_NetworkRequest = FALSE</code>.\n</li><li>Bei <code>Repetition Cycle completed [FrNm_NetworkRequest=FALSE AND FrNm_RepeatMessage=FALSE]</code> erfolgt der Wechsel nach <code>Ready Sleep</code> mit Zählerbelegung <code>FrNm_ReadySleepCnt = StartValue</code>.\n</li></ul>\n</li><li>In <code>Ready Sleep</code>:\n<ul class=\"fig-list\"><li>Solange <code>FrNm_NetworkRequest == FALSE AND FrNm_RepeatMessage == FALSE AND FrNm_ReadSleepCnt &gt; 0</code>, dekrementiert jeder Zyklus den Zähler: <code>/FrNm_ReadySleepCnt = FrNm_ReadySleepCnt - 1</code>.\n</li><li>Wird eine Netzwerkanforderung empfangen (<code>FrNm_NetworkRequest()</code>), wird <code>FrNm_NetworkRequest = TRUE</code> gesetzt und bei <code>FrNm_ReadySleepCnt &gt; 0</code> nach <code>Normal Operation</code> gewechselt.\n</li><li>Wird ein <code>ClusterAwakeVote detected</code>, wird <code>FrNm_ReadySleepCnt = StartValue</code> neu gesetzt.\n</li><li>Wenn <code>Repetition Cycle completed [FrNm_ReadySleepCnt &lt; 1]</code> eintritt, erfolgt über eine Exit-Verzweigung der Verlassen-Übergang von <code>Network Mode</code> in <code>Bus Sleep Mode</code> unter Auslösung von <code>/Nm_BusSleepMode</code>.\n</li></ul>\n</li><li>Übergeordnete Fehlerübergänge aus <code>Network Mode</code>:\n<ul class=\"fig-list\"><li><code>Retrieve global time fails [FrNmCycleCounterEmulation == FALSE AND Network is requested]</code> führt zurück nach <code>Synchronize</code>.\n</li><li>Reinitialisierung <code>FrNm_Init()</code> führt direkt nach <code>Bus Sleep Mode</code>.\n</li></ul>\n</li></ul>\n</li><li><strong>Herunterfahren:</strong>\n<ul class=\"fig-list\"><li>Aus <code>Bus Sleep Mode</code> führt <code>Power Off</code> in den Endzustand <code>Terminate</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Das Zustandsmodell legt die normativen Anforderungen an das AUTOSAR Classic FlexRay Network Management Modul fest.\n</li><li>Implementierer müssen sicherstellen, dass Guards unmittelbar im Zyklus der <code>FrNm_MainFunction</code> evaluiert und Transitionen verzögerungsfrei abgearbeitet werden, insbesondere beim Verlassen des <code>Network Mode</code> bei abgelaufenem <code>FrNm_ReadySleepCnt</code>.\n</li><li>Korrekte Pflege und synchrone Zählung von <code>FrNm_ReadySleepCnt</code> sowie das Rücksetzen bei externen Wachhalte-Votings (<code>ClusterAwakeVote detected</code>) sind essenziell für die koordinierte Cluster-Abschaltung.\n</li><li>Die Emulation des Zykluszählers (<code>FrNmCycleCounterEmulation</code>) bestimmt das Verhalten bei Verlust der globalen Zeitbasis.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-e830d9db65f376d1", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (State Machine Diagram) zur Spezifikation des Zustands- und Betriebsmodus-Verhaltens des AUTOSAR Classic Platform Basissoftware-Moduls FlexRay Network Management (<code>FrNm</code>). Das Diagramm definiert die übergeordneten Betriebsmodi (<code>Bus Sleep Mode</code>, <code>Synchronize</code>, <code>Network Mode</code>) sowie die hierarchischen Subzustände innerhalb des <code>Network Mode</code> (<code>Repeat Message</code>, <code>Normal Operation</code>, <code>Ready Sleep</code>) und deren Interaktion mit dem Zustand <code>Uninit</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Zustände:</strong>\n<ul class=\"fig-list\"><li><code>Uninit</code>: Initialer Ruhezustand vor der Modulinitialisierung.\n</li><li><code>Bus Sleep Mode</code>: Energiesparmodus ohne Kommunikation. Entry-Aktion: <code>entry / entry FrNm_NetworkRequest = FALSE FrNm_RepeatMessage = FALSE</code>.\n</li><li><code>Synchronize</code>: Synchronisationsphase zur Herstellung des globalen FlexRay-Zeittakts. Entry-Aktion: Benachrichtigung <code>entry / entry Notify &quot;Sychronize Mode&quot;</code>.\n</li><li><code>Network Mode</code>: Zusammengesetzter Zustand (Composite State) mit den Subzuständen:\n<ul class=\"fig-list\"><li><code>Repeat Message</code>: Wiederholtes Senden von NM-Botschaften. Entry-Aktion: <code>entry / entry Start RepeateMessage Timer</code>.\n</li><li><code>Normal Operation</code>: Regulärer aktiver NM-Betrieb mit Abstimmung zum Wachbleiben und Datenübertragung.\n</li><li><code>Ready Sleep</code>: Bereitschaft zum Übergang in den Schlafzustand; keine aktive Abstimmung zum Wachbleiben, keine Datenübertragung.\n</li></ul>\n</li></ul>\n</li><li><strong>Pseudozustände &amp; Endzustände:</strong>\n<ul class=\"fig-list\"><li>Initialzustände (Start-Pseudozustand) für Top-Level und Subzustände von <code>Network Mode</code>.\n</li><li>Verzweigungsknoten (Choice/Junction) für zyklische Überprüfungen und Bedingungsabzweige.\n</li><li>Terminierungs- bzw. Endzustand (<code>Terminate</code>) nach <code>Power Off</code>.\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Funktionsaufrufe (Trigger/Aktionen):</strong>\n<ul class=\"fig-list\"><li>APIs / Callbacks: <code>FrNm_Init()</code>, <code>FrNm_PassiveStartUp()</code>, <code>FrNm_NetworkRequest()</code>, <code>Nm_NetworkRequest()</code>, <code>FrNm_NetworkRelease()</code>.\n</li><li>Notifications: <code>/Notify &quot;Network Mode&quot;</code>, <code>/Nm_BusSleepMode</code>.\n</li><li>Interne Signale/Ereignisse: <code>RepeatMessagDetected</code>, <code>RepeatMessageTimer expired</code>, <code>Repetition Cycle completed</code>, <code>ClusterAwakeVote detected</code>, <code>Retrieve global time fails</code>.\n</li></ul>\n</li><li><strong>Statusvariablen &amp; Zähler:</strong>\n<ul class=\"fig-list\"><li><code>FrNm_NetworkRequest</code> (BOOLEAN)\n</li><li><code>FrNm_RepeatMessage</code> (BOOLEAN)\n</li><li><code>FrNm_ReadySleepCnt</code> (Ganzzahl/Zähler)\n</li><li>Konfigurationsparameter: <code>FrNmCycleCounterEmulation</code>, <code>StartValue</code>.\n</li></ul>\n</li><li><strong>Kommentar-Notizen:</strong>\n<ul class=\"fig-list\"><li>Kennzeichnung des Sende- und Abstimmungsverhaltens je Zustand (<code>Vote for keeping awake, Do data transmission</code> bzw. <code>No voting for keeping awake, No data transmission</code>).\n</li><li>Ausführungsbedingung für den Übergang aus <code>Network Mode</code> nach <code>Bus Sleep Mode</code>: sofortige Ausführung bei wahrer Guard-Bedingung im aktuellen MainFunction-Zyklus.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Initialisierung &amp; Hochlauf:</strong>\n<ul class=\"fig-list\"><li>Nach Systemstart (<code>Start</code>) befindet sich das Modul in <code>Uninit</code>.\n</li><li><code>FrNm_Init()</code> führt in den <code>Bus Sleep Mode</code>.\n</li><li>Aus <code>Bus Sleep Mode</code> führt <code>FrNm_PassiveStartUp()</code> oder <code>FrNm_NetworkRequest()</code> (mit Setzen von <code>FrNm_NetworkRequest = TRUE</code>) in den Zustand <code>Synchronize</code>.\n</li></ul>\n</li><li><strong>Synchronisation:</strong>\n<ul class=\"fig-list\"><li>In <code>Synchronize</code> wird auf den FlexRay-Zyklus aufsynchronisiert.\n</li><li>Bei erfolgreichem Zyklus (<code>Repetition Cycle completed</code>) erfolgt der Übergang in den <code>Network Mode</code> über einen Verzweigungspunkt: Wurde ein Netzwerk angefordert (<code>FrNm_NetworkRequest == TRUE</code>), führt der Pfad mit Aktion <code>/Notify &quot;Network Mode&quot;</code> und <code>FrNm_RepeatMessage = TRUE</code> in <code>Repeat Message</code>.\n</li><li>Schlägt die Synchronisation fehl (<code>Retrieve global time fails</code>), führt die Transition zurück nach <code>Synchronize</code>.\n</li><li>Reinitialisierung über <code>FrNm_Init()</code> oder Fehler (<code>[FrNm_Init OR (FrNm_NetworkRequested == FALSE AND FrNm_StartUp_Error Indication)]</code>) führt zurück in <code>Bus Sleep Mode</code>.\n</li></ul>\n</li><li><strong>Network Mode Zyklen &amp; Zustandswechsel:</strong>\n<ul class=\"fig-list\"><li>Nach Eintritt in <code>Network Mode</code> startet der Subzustand <code>Repeat Message</code> mit dem <code>RepeateMessage Timer</code>.\n</li><li>Bei Ablauf des Wiederholungszyklus (<code>Repetition Cycle completed</code>):\n<ul class=\"fig-list\"><li>Ist <code>FrNm_NetworkRequest == TRUE</code> und <code>FrNm_RepeatMessage == FALSE</code>, wechselt der Zustand zu <code>Normal Operation</code>.\n</li><li>Ist <code>FrNm_NetworkRequest == FALSE</code> und <code>FrNm_RepeatMessage == FALSE</code>, wechselt der Zustand zu <code>Ready Sleep</code> unter Initialisierung von <code>FrNm_ReadySleepCnt = StartValue</code>.\n</li><li>Ist <code>FrNm_ReadySleepCnt &gt; 0</code> und <code>FrNm_RepeatMessage == TRUE</code>, verbleibt bzw. verzweigt der Pfad in <code>Repeat Message</code>.\n</li></ul>\n</li><li>In <code>Normal Operation</code>:\n<ul class=\"fig-list\"><li><code>FrNm_NetworkRelease()</code> setzt <code>FrNm_NetworkRequest = FALSE</code>.\n</li><li>Bei <code>Repetition Cycle completed [FrNm_NetworkRequest=FALSE AND FrNm_RepeatMessage=FALSE]</code> erfolgt der Wechsel nach <code>Ready Sleep</code> mit Zählerbelegung <code>FrNm_ReadySleepCnt = StartValue</code>.\n</li></ul>\n</li><li>In <code>Ready Sleep</code>:\n<ul class=\"fig-list\"><li>Solange <code>FrNm_NetworkRequest == FALSE AND FrNm_RepeatMessage == FALSE AND FrNm_ReadSleepCnt &gt; 0</code>, dekrementiert jeder Zyklus den Zähler: <code>/FrNm_ReadySleepCnt = FrNm_ReadySleepCnt - 1</code>.\n</li><li>Wird eine Netzwerkanforderung empfangen (<code>FrNm_NetworkRequest()</code>), wird <code>FrNm_NetworkRequest = TRUE</code> gesetzt und bei <code>FrNm_ReadySleepCnt &gt; 0</code> nach <code>Normal Operation</code> gewechselt.\n</li><li>Wird ein <code>ClusterAwakeVote detected</code>, wird <code>FrNm_ReadySleepCnt = StartValue</code> neu gesetzt.\n</li><li>Wenn <code>Repetition Cycle completed [FrNm_ReadySleepCnt &lt; 1]</code> eintritt, erfolgt über eine Exit-Verzweigung der Verlassen-Übergang von <code>Network Mode</code> in <code>Bus Sleep Mode</code> unter Auslösung von <code>/Nm_BusSleepMode</code>.\n</li></ul>\n</li><li>Übergeordnete Fehlerübergänge aus <code>Network Mode</code>:\n<ul class=\"fig-list\"><li><code>Retrieve global time fails [FrNmCycleCounterEmulation == FALSE AND Network is requested]</code> führt zurück nach <code>Synchronize</code>.\n</li><li>Reinitialisierung <code>FrNm_Init()</code> führt direkt nach <code>Bus Sleep Mode</code>.\n</li></ul>\n</li></ul>\n</li><li><strong>Herunterfahren:</strong>\n<ul class=\"fig-list\"><li>Aus <code>Bus Sleep Mode</code> führt <code>Power Off</code> in den Endzustand <code>Terminate</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Das Zustandsmodell legt die normativen Anforderungen an das AUTOSAR Classic FlexRay Network Management Modul fest.\n</li><li>Implementierer müssen sicherstellen, dass Guards unmittelbar im Zyklus der <code>FrNm_MainFunction</code> evaluiert und Transitionen verzögerungsfrei abgearbeitet werden, insbesondere beim Verlassen des <code>Network Mode</code> bei abgelaufenem <code>FrNm_ReadySleepCnt</code>.\n</li><li>Korrekte Pflege und synchrone Zählung von <code>FrNm_ReadySleepCnt</code> sowie das Rücksetzen bei externen Wachhalte-Votings (<code>ClusterAwakeVote detected</code>) sind essenziell für die koordinierte Cluster-Abschaltung.\n</li><li>Die Emulation des Zykluszählers (<code>FrNmCycleCounterEmulation</code>) bestimmt das Verhalten bei Verlust der globalen Zeitbasis.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-70295554985bb1df", "to": "FIG-618a12c348b10353", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-618a12c348b10353", "to": "FIG-049daa5ed1aeb697", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-049daa5ed1aeb697", "to": "FIG-17c44f137303b916", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-17c44f137303b916", "to": "FIG-e830d9db65f376d1", "fr": "R21-11", "tr": "R22-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Zustände <code>Bus Sleep Mode</code>, <code>Synchronize</code> und <code>Repeat Message</code>: Das Präfix <code>+ </code> vor den <code>entry / entry</code>-Aktionen entfällt.\n</li></ul>"}]};
